[CmdletBinding()]
param(
    [switch]$SimulateLowSpace
)

$ErrorActionPreference = "Stop"

$projectPath = $PSScriptRoot
$checkScript = Join-Path $projectPath "Check-DiskSpace.ps1"
$remediationScript = Join-Path $projectPath "Invoke-DiskSpaceRemediation.ps1"
$incidentLog = Join-Path $projectPath "incident-response-log.csv"

Write-Host "=== IT Incident Response Automation ===" -ForegroundColor Cyan

# Step 1: Run disk-space check
if ($SimulateLowSpace) {
    $checkOutput = & $checkScript -SimulateLowSpace
}
else {
    $checkOutput = & $checkScript
}


# Use the result generated by the current disk-space check
$latestCheck = $checkOutput |
    Where-Object { $_ -is [PSCustomObject] -and $_.PSObject.Properties["Status"] } |
    Select-Object -Last 1

if (-not $latestCheck) {
    throw "The current disk-space check did not return a valid result."
}

# Step 2: Decide what happens next
$decision = "No remediation required"
$remediationResult = "Not required"

if ($latestCheck.Status -eq "LOW_DISK_SPACE") {
    if ($latestCheck.TestMode -eq "True") {
        $decision = "Simulated incident: run lab remediation"
        & $remediationScript -LabSimulation
        $remediationResult = "Lab remediation executed"
    }
    else {
        $decision = "Low disk space detected: remediation not run"
        $remediationResult = "Manual review required"
    }
}
elseif ($latestCheck.Status -eq "HEALTHY") {
    $decision = "Disk space healthy"
    $remediationResult = "Not required"
}
else {
    $decision = "Unknown status"
    $remediationResult = "Manual review required"
}

# Step 3: Record the overall incident response
[PSCustomObject]@{
    Timestamp          = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    DiskStatus         = $latestCheck.Status
    FreeGB             = $latestCheck.FreeGB
    Severity           = $latestCheck.Severity
    TestMode           = $latestCheck.TestMode
    Decision           = $decision
    RemediationResult  = $remediationResult
} | Export-Csv -LiteralPath $incidentLog -Append -NoTypeInformation -Encoding UTF8

Write-Host ""
Write-Host "Disk status: $($latestCheck.Status)"
Write-Host "Decision: $decision"
Write-Host "Remediation: $remediationResult"
Write-Host "Incident log: $incidentLog"